"use client"

import React, { useRef, useState, useEffect } from 'react';
import { PlayIcon, PauseIcon, MuteIcon, UnmuteIcon, TranscriptIcon, SpeedIcon, CCIcon, FullscreenIcon, PiPIcon, VolumeIcon, AudioDescIcon, ChaptersIcon, SettingsIcon, InfoIcon, QualityIcon } from './icons';
import AudioDescSettingsModal from './AudioDescSettingsModal';
import ChaptersSidebar from './ChaptersSidebar';
import Transcript from './Transcript';
import SettingsModal from './SettingsModal';
import InfoModal from './InfoModal';
import { FullPlayerProps, VideoSources } from '../types/player';
import { useTranscriptData, useChaptersData, useVoicesData } from '../hooks/useVideoData';
import { formatTime, addPlayerStyles } from '../utils/videoUtils';
import { extractBundestagVideo } from '../utils/videoExtractors';
import { YouTubePlayerWrapper, extractYouTubeId } from '../utils/youtubePlayer';
import { VimeoPlayerWrapper, extractVimeoId } from '../utils/vimeoPlayer';
import { LOCAL } from '../app/layout';

const FullPlayer: React.FC<FullPlayerProps> = ({ 
  mp4, 
  webm, 
  youtube, 
  vimeo, 
  btag, 
  captions, 
  description, 
  chapters, 
  autoplay = false, 
  muted = true // Standard: Ton aus
}) => {
  // Refs
  const videoRef = useRef<HTMLVideoElement>(null);
  const controlsRef = useRef<HTMLDivElement>(null);
  const spoolingRef = useRef<NodeJS.Timeout | null>(null);
  const lastDescIdxRef = useRef<number>(-1);
  const youtubeContainerRef = useRef<HTMLDivElement>(null);
  const youtubePlayerRef = useRef<YouTubePlayerWrapper | null>(null);
  const vimeoContainerRef = useRef<HTMLDivElement>(null);
  const vimeoPlayerRef = useRef<VimeoPlayerWrapper | null>(null);
  const timeUpdateIntervalRef = useRef<NodeJS.Timeout | null>(null);

  // Basic player state mit korrekten Defaults
  const [isPlaying, setIsPlaying] = useState(!autoplay); // Standard: Pause
  const [isMuted, setIsMuted] = useState(muted); // Standard: Ton aus
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(1); // Standard: 100%
  const [playbackRate, setPlaybackRate] = useState(1); // Standard: 1x
  const [controlsVisible, setControlsVisible] = useState(true);
  const [isPiPSupported, setIsPiPSupported] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // UI state mit korrekten Defaults
  const [showTranscript, setShowTranscript] = useState(false); // Nur wenn description in LOCAL verfügbar
  const [showCC, setShowCC] = useState(false); // Nur wenn captions in LOCAL verfügbar
  const [showChapters, setShowChapters] = useState(false); // Standard: off
  const [isSpooling, setIsSpooling] = useState(false);

  // Modal states
  const [audioDescSettingsOpen, setAudioDescSettingsOpen] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [infoOpen, setInfoOpen] = useState(false);

  // Audio description state
  const [audioDescActive, setAudioDescActive] = useState(false); // Nur wenn description verfügbar
  const [ttsBusy, setTtsBusy] = useState(false);
  const [pitch, setPitch] = useState(1);
  const [autoStop, setAutoStop] = useState(true);
  const [autoStart, setAutoStart] = useState(true);
  const [audioDescMode, setAudioDescMode] = useState<'tts' | 'audio' | 'sign'>('tts');
  const [ttsAvailable, setTtsAvailable] = useState(true);
  const [ttsError, setTtsError] = useState('');
  const [hasAudioTrack, setHasAudioTrack] = useState(false);
  const [hasSignTrack, setHasSignTrack] = useState(false);

  // Content indexes
  const [currentCueIdx, setCurrentCueIdx] = useState<number>(-1);
  const [currentChapterIdx, setCurrentChapterIdx] = useState(-1);

  // Video sources and quality
  const [videoSources, setVideoSources] = useState<VideoSources>({});
  const [selectedQuality, setSelectedQuality] = useState<string>('auto');
  const [videoSrc, setVideoSrc] = useState<string>('');

  // Player type state
  const [playerType, setPlayerType] = useState<'video' | 'youtube' | 'vimeo' | 'btag'>('video');
  const [youtubePlayerId] = useState(`youtube-player-${Math.random().toString(36).substr(2, 9)}`);
  const [vimeoPlayerId] = useState(`vimeo-player-${Math.random().toString(36).substr(2, 9)}`);

  // Data hooks
  const cues = useTranscriptData(captions, description);
  const parsedChapters = useChaptersData(chapters);
  const { voices, selectedVoice, setSelectedVoice } = useVoicesData();

  // Video source resolution mit Quality Support
  useEffect(() => {
    const resolveVideoSource = async () => {
      setIsLoading(true);
      try {
        if (mp4 || webm) {
          setPlayerType('video');
          const sources: VideoSources = {};
          
          if (mp4) {
            // Support für verschiedene MP4 Qualitäten
            if (Array.isArray(mp4)) {
              sources.mp4 = mp4.map((url, index) => ({
                url,
                quality: `Quality ${index + 1}`,
                width: 1920,
                height: 1080
              }));
            } else {
              sources.mp4 = [{ url: mp4, quality: 'Original', width: 1920, height: 1080 }];
            }
          }
          
          if (webm) {
            // Support für verschiedene WebM Qualitäten
            if (Array.isArray(webm)) {
              sources.webm = webm.map((url, index) => ({
                url,
                quality: `Quality ${index + 1}`,
                width: 1920,
                height: 1080
              }));
            } else {
              sources.webm = [{ url: webm, quality: 'Original', width: 1920, height: 1080 }];
            }
          }
          
          setVideoSources(sources);
          
          // Wähle erste verfügbare Quelle
          if (sources.mp4?.[0]) {
            setVideoSrc(sources.mp4[0].url);
            setSelectedQuality(sources.mp4[0].quality);
          } else if (sources.webm?.[0]) {
            setVideoSrc(sources.webm[0].url);
            setSelectedQuality(sources.webm[0].quality);
          }
          
        } else if (youtube) {
          setPlayerType('youtube');
        } else if (vimeo) {
          setPlayerType('vimeo');
        } else if (btag) {
          setPlayerType('btag');
          const sources = await extractBundestagVideo(btag);
          setVideoSources(sources);
          if (sources.mp4?.[0]) {
            setVideoSrc(sources.mp4[0].url);
            setSelectedQuality(sources.mp4[0].quality);
          }
        }
      } catch (error) {
        console.error('Video source resolution failed:', error);
      } finally {
        setIsLoading(false);
      }
    };

    resolveVideoSource();
  }, [mp4, webm, youtube, vimeo, btag]);

  // YouTube player initialization
  useEffect(() => {
    if (playerType === 'youtube' && youtube) {
      const initYouTubePlayer = async () => {
        const videoId = extractYouTubeId(youtube);
        if (!videoId) return;

        if (youtubeContainerRef.current) {
          youtubeContainerRef.current.innerHTML = `<div id="${youtubePlayerId}"></div>`;
          
          try {
            const ytPlayer = new YouTubePlayerWrapper(youtubePlayerId, videoId);
            await ytPlayer.init();
            youtubePlayerRef.current = ytPlayer;

            // Event listeners
            ytPlayer.on('ready', () => {
              setDuration(ytPlayer.getDuration());
              if (muted) ytPlayer.mute();
              setVolume(ytPlayer.getVolume());
              
              // Time update interval für YouTube
              timeUpdateIntervalRef.current = setInterval(() => {
                setCurrentTime(ytPlayer.getCurrentTime());
              }, 100);
            });

            ytPlayer.on('play', () => setIsPlaying(true));
            ytPlayer.on('pause', () => setIsPlaying(false));
            ytPlayer.on('ended', () => setIsPlaying(false));

          } catch (error) {
            console.error('Failed to initialize YouTube player:', error);
          }
        }
      };

      initYouTubePlayer();
    }

    return () => {
      if (youtubePlayerRef.current) {
        youtubePlayerRef.current.destroy();
        youtubePlayerRef.current = null;
      }
      if (timeUpdateIntervalRef.current) {
        clearInterval(timeUpdateIntervalRef.current);
        timeUpdateIntervalRef.current = null;
      }
    };
  }, [playerType, youtube, youtubePlayerId, muted]);

  // Vimeo player initialization
  useEffect(() => {
    if (playerType === 'vimeo' && vimeo) {
      const initVimeoPlayer = async () => {
        const videoId = extractVimeoId(vimeo);
        if (!videoId) return;

        if (vimeoContainerRef.current) {
          vimeoContainerRef.current.innerHTML = `<div id="${vimeoPlayerId}"></div>`;
          
          try {
            const vimeoPlayer = new VimeoPlayerWrapper(vimeoPlayerId, videoId);
            await vimeoPlayer.init();
            vimeoPlayerRef.current = vimeoPlayer;

            // Event listeners
            vimeoPlayer.on('ready', async () => {
              const duration = await vimeoPlayer.getDuration();
              setDuration(duration);
              if (muted) await vimeoPlayer.mute();
              const volume = await vimeoPlayer.getVolume();
              setVolume(volume);
            });

            vimeoPlayer.on('play', () => setIsPlaying(true));
            vimeoPlayer.on('pause', () => setIsPlaying(false));
            vimeoPlayer.on('ended', () => setIsPlaying(false));
            vimeoPlayer.on('timeupdate', (data) => {
              setCurrentTime(data.seconds);
            });

          } catch (error) {
            console.error('Failed to initialize Vimeo player:', error);
          }
        }
      };

      initVimeoPlayer();
    }

    return () => {
      if (vimeoPlayerRef.current) {
        vimeoPlayerRef.current.destroy();
        vimeoPlayerRef.current = null;
      }
    };
  }, [playerType, vimeo, vimeoPlayerId, muted]);

  // Verfügbarkeit von Features prüfen
  useEffect(() => {
    // CC nur anzeigen wenn captions in LOCAL verfügbar
    setShowCC(!!captions && captions.includes(`_${LOCAL}.vtt`));
    
    // Transcript nur anzeigen wenn description in LOCAL verfügbar
    setShowTranscript(!!description && description.includes(`_${LOCAL}.vtt`));
    
    // AudioDescription nur aktivieren wenn verfügbar
    setAudioDescActive(!!description || hasAudioTrack);
  }, [captions, description, hasAudioTrack]);

  // Quality selection handler
  const handleQualityChange = (quality: string, format: 'mp4' | 'webm') => {
    setSelectedQuality(quality);
    
    const sources = videoSources[format];
    if (sources) {
      const selectedSource = sources.find(source => source.quality === quality);
      if (selectedSource && (playerType === 'video' || playerType === 'btag')) {
        const currentTime = getCurrentPlayerTime();
        const wasPlaying = isPlaying;
        
        setVideoSrc(selectedSource.url);
        
        // Restore time and playing state after source change
        setTimeout(() => {
          if (videoRef.current) {
            videoRef.current.currentTime = currentTime;
            if (wasPlaying) {
              videoRef.current.play();
            }
          }
        }, 100);
      }
    }
  };

  // Unified control handlers
  const getCurrentPlayerTime = (): number => {
    if (playerType === 'youtube' && youtubePlayerRef.current) {
      return youtubePlayerRef.current.getCurrentTime();
    } else if (playerType === 'vimeo' && vimeoPlayerRef.current) {
      // Async für Vimeo, aber wir verwenden den State
      return currentTime;
    } else if (videoRef.current) {
      return videoRef.current.currentTime;
    }
    return 0;
  };

  const handlePlay = async () => {
    if (playerType === 'youtube' && youtubePlayerRef.current) {
      youtubePlayerRef.current.play();
    } else if (playerType === 'vimeo' && vimeoPlayerRef.current) {
      await vimeoPlayerRef.current.play();
    } else if (videoRef.current) {
      await videoRef.current.play();
    }
  };

  const handlePause = async () => {
    if (playerType === 'youtube' && youtubePlayerRef.current) {
      youtubePlayerRef.current.pause();
    } else if (playerType === 'vimeo' && vimeoPlayerRef.current) {
      await vimeoPlayerRef.current.pause();
    } else if (videoRef.current) {
      videoRef.current.pause();
    }
  };

  const handleSeek = async (time: number) => {
    if (playerType === 'youtube' && youtubePlayerRef.current) {
      youtubePlayerRef.current.seekTo(time);
    } else if (playerType === 'vimeo' && vimeoPlayerRef.current) {
      await vimeoPlayerRef.current.seekTo(time);
    } else if (videoRef.current) {
      videoRef.current.currentTime = time;
    }
  };

  const handleVolumeChange = async (newVolume: number) => {
    setVolume(newVolume);
    if (playerType === 'youtube' && youtubePlayerRef.current) {
      youtubePlayerRef.current.setVolume(newVolume);
    } else if (playerType === 'vimeo' && vimeoPlayerRef.current) {
      await vimeoPlayerRef.current.setVolume(newVolume);
    } else if (videoRef.current) {
      videoRef.current.volume = newVolume;
    }
  };

  const handleMuteToggle = async () => {
    const newMuted = !isMuted;
    setIsMuted(newMuted);
    
    if (playerType === 'youtube' && youtubePlayerRef.current) {
      if (newMuted) {
        youtubePlayerRef.current.mute();
      } else {
        youtubePlayerRef.current.unmute();
      }
    } else if (playerType === 'vimeo' && vimeoPlayerRef.current) {
      if (newMuted) {
        await vimeoPlayerRef.current.mute();
      } else {
        await vimeoPlayerRef.current.unmute();
      }
    } else if (videoRef.current) {
      videoRef.current.muted = newMuted;
    }
  };

  const handlePlaybackRateChange = async (rate: number) => {
    setPlaybackRate(rate);
    if (playerType === 'youtube' && youtubePlayerRef.current) {
      youtubePlayerRef.current.setPlaybackRate(rate);
    } else if (playerType === 'vimeo' && vimeoPlayerRef.current) {
      await vimeoPlayerRef.current.setPlaybackRate(rate);
    } else if (videoRef.current) {
      videoRef.current.playbackRate = rate;
    }
  };

  // Chapter highlighting
  useEffect(() => {
    if (parsedChapters.length === 0) return;
    const idx = parsedChapters.findIndex(ch => currentTime >= ch.start && currentTime < ch.end);
    setCurrentChapterIdx(idx);
  }, [currentTime, parsedChapters]);

  // Video event listeners für native video
  useEffect(() => {
    const video = videoRef.current;
    if (!video || playerType !== 'video' && playerType !== 'btag') return;
    
    const onTimeUpdate = () => setCurrentTime(video.currentTime);
    const onLoaded = () => setDuration(video.duration);
    
    video.addEventListener('timeupdate', onTimeUpdate);
    video.addEventListener('loadedmetadata', onLoaded);
    
    return () => {
      video.removeEventListener('timeupdate', onTimeUpdate);
      video.removeEventListener('loadedmetadata', onLoaded);
    };
  }, [playerType]);

  // Auto-hide controls
  useEffect(() => {
    if (!controlsVisible || !isPlaying) return;
    const timeout = setTimeout(() => setControlsVisible(false), 3000);
    return () => clearTimeout(timeout);
  }, [controlsVisible, isPlaying, currentTime]);

  // Show controls on interaction
  useEffect(() => {
    const show = () => setControlsVisible(true);
    window.addEventListener('mousemove', show);
    window.addEventListener('keydown', show);
    return () => {
      window.removeEventListener('mousemove', show);
      window.removeEventListener('keydown', show);
    };
  }, []);

  // PiP support check
  useEffect(() => {
    setIsPiPSupported(!!(document as any).pictureInPictureEnabled && typeof (videoRef.current as any)?.requestPictureInPicture === 'function');
  }, []);

  // Track detection
  useEffect(() => {
    const checkTracks = () => {
      const video = videoRef.current;
      if (!video) return;
      setHasAudioTrack(!!video.querySelector('track[kind="descriptions"]'));
      setHasSignTrack(!!video.querySelector('track[kind="sign"]'));
    };
    checkTracks();
  }, []);

  // TTS availability check
  useEffect(() => {
    if (!('speechSynthesis' in window)) {
      setTtsAvailable(false);
      setTtsError('Text-to-Speech wird von diesem Browser nicht unterstützt.');
    } else {
      setTtsAvailable(true);
      setTtsError('');
    }
  }, []);

  // Audio description logic (funktioniert nur bei native video)
  useEffect(() => {
    if (!videoRef.current || cues.length === 0 || playerType !== 'video' && playerType !== 'btag') return;
    const video = videoRef.current;
    let ttsUtter: SpeechSynthesisUtterance | null = null;

    const onTimeUpdate = () => {
      const t = video.currentTime;
      const idx = cues.findIndex(cue => t >= cue.start && t <= cue.end && (
        (audioDescMode === 'tts' && cue.type === 'description') ||
        (audioDescMode === 'tts' && cue.type === 'caption' && !cues.some(c => c.type === 'description'))
      ));
      
      setCurrentCueIdx(idx);
      
      if (
        audioDescActive &&
        audioDescMode === 'tts' &&
        idx !== -1 &&
        !ttsBusy &&
        lastDescIdxRef.current !== idx &&
        ttsAvailable
      ) {
        setTtsBusy(true);
        lastDescIdxRef.current = idx;
        if (autoStop) video.pause();
        
        ttsUtter = new window.SpeechSynthesisUtterance(cues[idx].text);
        ttsUtter.voice = voices.find(v => v.voiceURI === selectedVoice) || null;
        ttsUtter.pitch = pitch;
        ttsUtter.onend = () => {
          setTtsBusy(false);
          if (autoStart) video.play();
        };
        window.speechSynthesis.speak(ttsUtter);
      }
      
      if (idx === -1) {
        lastDescIdxRef.current = -1;
      }
    };

    video.addEventListener('timeupdate', onTimeUpdate);
    return () => {
      video.removeEventListener('timeupdate', onTimeUpdate);
      if (ttsUtter) window.speechSynthesis.cancel();
    };
  }, [cues, audioDescActive, ttsBusy, voices, selectedVoice, pitch, autoStop, autoStart, audioDescMode, ttsAvailable, playerType]);

  // CC toggle effect (nur für native video)
  useEffect(() => {
    if (videoRef.current && (playerType === 'video' || playerType === 'btag')) {
      const tracks = videoRef.current.textTracks;
      for (let i = 0; i < tracks.length; i++) {
        if (tracks[i].kind === 'subtitles') {
          tracks[i].mode = showCC ? 'showing' : 'hidden';
        }
      }
    }
  }, [showCC, captions, playerType]);

  // Styles
  useEffect(() => {
    return addPlayerStyles();
  }, []);

  // Control handlers
  const handleFullscreen = () => {
    const element = playerType === 'youtube' ? youtubeContainerRef.current : 
                   playerType === 'vimeo' ? vimeoContainerRef.current : 
                   videoRef.current;
                   
    if (element) {
      if (document.fullscreenElement) {
        document.exitFullscreen();
      } else {
        element.requestFullscreen();
      }
    }
  };

  const handlePiP = () => {
    if (videoRef.current && (videoRef.current as any).requestPictureInPicture && (playerType === 'video' || playerType === 'btag')) {
      (videoRef.current as any).requestPictureInPicture();
    }
  };

  const handleSpool = (dir: 'back' | 'forward') => {
    if (playerType !== 'video' && playerType !== 'btag') return;
    if (!videoRef.current) return;
    setIsSpooling(true);
    videoRef.current.muted = true;
    spoolingRef.current = setInterval(() => {
      if (!videoRef.current) return;
      videoRef.current.currentTime += dir === 'forward' ? 0.2 : -0.2;
    }, 20);
  };

  const stopSpool = () => {
    setIsSpooling(false);
    if (spoolingRef.current) clearInterval(spoolingRef.current);
    if (videoRef.current) videoRef.current.muted = !!isMuted;
  };

  const handleChapterClick = (startTime: number) => {
    handleSeek(startTime);
  };

  // Get available qualities for dropdown
  const getAvailableQualities = () => {
    const qualities: Array<{label: string, value: string, format: 'mp4' | 'webm'}> = [];
    
    if (videoSources.mp4) {
      videoSources.mp4.forEach(source => {
        qualities.push({
          label: `${source.quality} (MP4) - ${source.width}x${source.height}`,
          value: source.quality,
          format: 'mp4'
        });
      });
    }
    
    if (videoSources.webm) {
      videoSources.webm.forEach(source => {
        qualities.push({
          label: `${source.quality} (WebM) - ${source.width}x${source.height}`,
          value: source.quality,
          format: 'webm'
        });
      });
    }
    
    return qualities;
  };

  const availableQualities = getAvailableQualities();

  return (
    <section aria-label="Barrierefreier Video Player" style={{ maxWidth: '100%', display: 'flex', flexDirection: 'row', alignItems: 'flex-start', gap: 16 }}>
      <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column' }}>
        
        {/* Loading State */}
        {isLoading && (
          <div style={{ width: '100%', height: 400, display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#f0f0f0', borderRadius: 8 }}>
            <span>Video wird geladen...</span>
          </div>
        )}

        {/* Native Video Player */}
        {!isLoading && (playerType === 'video' || playerType === 'btag') && (
          <video
            ref={videoRef}
            width="100%"
            height="400"
            aria-label="Video mit Untertiteln und Beschreibung"
            muted={isMuted}
            tabIndex={0}
            onPlay={() => setIsPlaying(true)}
            onPause={() => setIsPlaying(false)}
            autoPlay={autoplay}
            playsInline
            crossOrigin="anonymous"
            style={{ borderRadius: 8 }}
          >
            {videoSrc && <source src={videoSrc} type="video/mp4" />}
            {captions && <track kind="subtitles" src={captions} srcLang={LOCAL} label="Untertitel" default />}
            {description && <track kind="descriptions" src={description} srcLang={LOCAL} label="Audiodeskription" />}
            {chapters && <track kind="chapters" src={chapters} srcLang={LOCAL} label="Kapitel" />}
          </video>
        )}

        {/* YouTube Player Container */}
        {!isLoading && playerType === 'youtube' && (
          <div 
            ref={youtubeContainerRef}
            style={{ width: '100%', height: '400px', borderRadius: 8, overflow: 'hidden' }}
            aria-label="YouTube Video Player"
          />
        )}

        {/* Vimeo Player Container */}
        {!isLoading && playerType === 'vimeo' && (
          <div 
            ref={vimeoContainerRef}
            style={{ width: '100%', height: '400px', borderRadius: 8, overflow: 'hidden' }}
            aria-label="Vimeo Video Player"
          />
        )}

        {/* Quality Selector */}
        {availableQualities.length > 1 && (
          <div style={{ marginTop: 8, display: 'flex', alignItems: 'center', gap: 8 }}>
            <QualityIcon aria-label="Qualität" />
            <label htmlFor="quality-select" style={{ fontWeight: 500 }}>Qualität:</label>
            <select 
              id="quality-select"
              value={selectedQuality} 
              onChange={e => {
                const selectedOption = availableQualities.find(q => q.value === e.target.value);
                if (selectedOption) {
                  handleQualityChange(e.target.value, selectedOption.format);
                }
              }}
              style={{ padding: 8, borderRadius: 4, border: '1px solid #ccc', background: 'white' }}
            >
              {availableQualities.map(quality => (
                <option key={`${quality.format}-${quality.value}`} value={quality.value}>
                  {quality.label}
                </option>
              ))}
            </select>
          </div>
        )}

        {/* Progress Bar */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 8, width: '100%' }}>
          <span style={{ minWidth: 48, textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontSize: 14 }}>
            {formatTime(currentTime)}
          </span>
          <input
            type="range"
            min={0}
            max={duration || 1}
            step={0.01}
            value={currentTime}
            onChange={e => handleSeek(Number(e.target.value))}
            aria-label="Fortschritt"
            style={{ 
              flex: 1, 
              height: 6,
              borderRadius: 3,
              background: `linear-gradient(to right, #007acc 0%, #007acc ${(currentTime / duration) * 100}%, #ddd ${(currentTime / duration) * 100}%, #ddd 100%)`
            }}
          />
          <span style={{ minWidth: 48, textAlign: 'left', fontVariantNumeric: 'tabular-nums', fontSize: 14 }}>
            {formatTime(duration)}
          </span>
        </div>

        {/* Controls */}
        {controlsVisible && (
          <nav 
            ref={controlsRef} 
            aria-label="Player-Steuerung" 
            style={{ 
              marginTop: 12, 
              display: 'flex', 
              gap: 4, 
              flexWrap: 'wrap', 
              alignItems: 'center', 
              background: 'rgba(0,0,0,0.8)', 
              borderRadius: 8, 
              padding: 12,
              color: 'white'
            }}
          >
            {/* Basic Controls */}
            <button 
              className="player-btn" 
              onClick={() => handleSeek(0)} 
              aria-label="Zum Start" 
              title="Zum Start"
              style={{ padding: 8, background: 'none', border: 'none', color: 'white', cursor: 'pointer', borderRadius: 4 }}
            >
              |&#9664;
            </button>
            
            <button 
              className="player-btn" 
              onClick={isPlaying ? handlePause : handlePlay} 
              aria-label={isPlaying ? 'Pause' : 'Abspielen'} 
              title={isPlaying ? 'Pause' : 'Abspielen'}
              style={{ padding: 8, background: 'none', border: 'none', color: 'white', cursor: 'pointer', borderRadius: 4 }}
            >
              {isPlaying ? <PauseIcon aria-label="Pause" /> : <PlayIcon aria-label="Abspielen" />}
            </button>

            <button
              className="player-btn"
              onClick={() => handleSeek(Math.max(0, currentTime - 10))}
              onMouseDown={() => handleSpool('back')}
              onMouseUp={stopSpool}
              onMouseLeave={stopSpool}
              onTouchStart={() => handleSpool('back')}
              onTouchEnd={stopSpool}
              aria-label="10 Sekunden zurück" 
              title="10 Sekunden zurück"
              style={{ padding: 8, background: 'none', border: 'none', color: 'white', cursor: 'pointer', borderRadius: 4 }}
            >
              &#9664;10s
            </button>

            <button
              className="player-btn"
              onClick={() => handleSeek(Math.min(duration, currentTime + 10))}
              onMouseDown={() => handleSpool('forward')}
              onMouseUp={stopSpool}
              onMouseLeave={stopSpool}
              onTouchStart={() => handleSpool('forward')}
              onTouchEnd={stopSpool}
              aria-label="10 Sekunden vor" 
              title="10 Sekunden vor"
              style={{ padding: 8, background: 'none', border: 'none', color: 'white', cursor: 'pointer', borderRadius: 4 }}
            >
              10s&#9654;
            </button>

            <div style={{ width: 1, height: 24, background: '#666', margin: '0 8px' }} />

            {/* Audio Controls */}
            <button 
              className="player-btn" 
              onClick={handleMuteToggle} 
              aria-label={isMuted ? 'Ton an' : 'Ton aus'} 
              title={isMuted ? 'Ton an' : 'Ton aus'}
              style={{ padding: 8, background: 'none', border: 'none', color: 'white', cursor: 'pointer', borderRadius: 4 }}
            >
              {isMuted ? <UnmuteIcon aria-label="Ton an" /> : <MuteIcon aria-label="Ton aus" />}
            </button>

            <span style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <VolumeIcon aria-label="Lautstärke" />
              <input
                type="range"
                min={0}
                max={1}
                step={0.01}
                value={volume}
                onChange={e => handleVolumeChange(Number(e.target.value))}
                aria-label="Lautstärke"
                style={{ width: 80 }}
              />
              <span style={{ minWidth: 32, fontSize: 12 }}>{Math.round(volume * 100)}%</span>
            </span>

            <div style={{ width: 1, height: 24, background: '#666', margin: '0 8px' }} />

            {/* Speed Control */}
            <span style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <SpeedIcon style={{verticalAlign:'middle'}} aria-label="Geschwindigkeit" />
              <input
                type="range"
                min={0.5}
                max={2}
                step={0.05}
                value={playbackRate}
                onChange={e => handlePlaybackRateChange(Number(e.target.value))}
                aria-label="Geschwindigkeit"
                style={{ width: 80 }}
              />
              <span style={{ minWidth: 40, textAlign: 'center', fontSize: 12 }}>{playbackRate.toFixed(2)}x</span>
            </span>

            <div style={{ width: 1, height: 24, background: '#666', margin: '0 8px' }} />

            {/* Feature Toggles */}
            {captions && (
              <button 
                className="player-btn" 
                onClick={() => setShowCC(v => !v)} 
                aria-pressed={showCC} 
                aria-label="Untertitel ein-/ausblenden" 
                title="Untertitel ein-/ausblenden"
                style={{ 
                  padding: 8, 
                  background: showCC ? '#007acc' : 'none', 
                  border: 'none', 
                  color: 'white', 
                  cursor: 'pointer', 
                  borderRadius: 4 
                }}
              >
                <CCIcon style={{verticalAlign:'middle'}} aria-label="CC" />
              </button>
            )}

            {chapters && (
              <button 
                className="player-btn" 
                onClick={() => setShowChapters(v => !v)} 
                aria-pressed={showChapters} 
                aria-label="Kapitel anzeigen/verbergen" 
                title="Kapitel anzeigen/verbergen"
                style={{ 
                  padding: 8, 
                  background: showChapters ? '#007acc' : 'none', 
                  border: 'none', 
                  color: 'white', 
                  cursor: 'pointer', 
                  borderRadius: 4 
                }}
              >
                <ChaptersIcon style={{verticalAlign:'middle'}} aria-label="Kapitel" />
              </button>
            )}

            {description && (
              <button 
                className="player-btn" 
                onClick={() => setShowTranscript(v => !v)} 
                aria-pressed={showTranscript} 
                aria-label="Transkript anzeigen/verbergen" 
                title="Transkript anzeigen/verbergen"
                style={{ 
                  padding: 8, 
                  background: showTranscript ? '#007acc' : 'none', 
                  border: 'none', 
                  color: 'white', 
                  cursor: 'pointer', 
                  borderRadius: 4 
                }}
              >
                <TranscriptIcon style={{verticalAlign:'middle'}} aria-label="Transkript" />
              </button>
            )}

            {(description || hasAudioTrack) && (
              <button
                className="player-btn"
                onClick={() => setAudioDescSettingsOpen(true)}
                aria-pressed={audioDescActive}
                aria-label="Audiodeskription Einstellungen"
                title="Audiodeskription Einstellungen"
                style={{ 
                  padding: 8, 
                  background: audioDescActive ? '#007acc' : 'none', 
                  border: 'none', 
                  color: 'white', 
                  cursor: 'pointer', 
                  borderRadius: 4 
                }}
              >
                <AudioDescIcon style={{verticalAlign:'middle'}} aria-label="Audiodeskription" />
              </button>
            )}

            <div style={{ width: 1, height: 24, background: '#666', margin: '0 8px' }} />

            {/* Additional Controls */}
            <button 
              className="player-btn" 
              onClick={handleFullscreen} 
              aria-label="Vollbild" 
              title="Vollbild"
              style={{ padding: 8, background: 'none', border: 'none', color: 'white', cursor: 'pointer', borderRadius: 4 }}
            >
              <FullscreenIcon style={{verticalAlign:'middle'}} aria-label="Vollbild" />
            </button>

            {isPiPSupported && (playerType === 'video' || playerType === 'btag') && (
              <button 
                className="player-btn" 
                onClick={handlePiP} 
                aria-label="Bild-in-Bild" 
                title="Bild-in-Bild"
                style={{ padding: 8, background: 'none', border: 'none', color: 'white', cursor: 'pointer', borderRadius: 4 }}
              >
                <PiPIcon style={{verticalAlign:'middle'}} aria-label="Bild-in-Bild" />
              </button>
            )}

            <button 
              className="player-btn" 
              onClick={() => setSettingsOpen(true)} 
              aria-label="Einstellungen" 
              title="Einstellungen"
              style={{ padding: 8, background: 'none', border: 'none', color: 'white', cursor: 'pointer', borderRadius: 4 }}
            >
              <SettingsIcon style={{verticalAlign:'middle'}} aria-label="Einstellungen" />
            </button>

            <button 
              className="player-btn" 
              onClick={() => setInfoOpen(true)} 
              aria-label="Informationen und Tastaturnavigation" 
              title="Informationen und Tastaturnavigation"
              style={{ padding: 8, background: 'none', border: 'none', color: 'white', cursor: 'pointer', borderRadius: 4 }}
            >
              <InfoIcon style={{verticalAlign:'middle'}} aria-label="Info" />
            </button>
          </nav>
        )}

        {/* Transcript */}
        {showTranscript && (
          <Transcript 
            cues={cues.filter(cue => cue.type === 'description')}
            currentCueIdx={currentCueIdx}
            visible={showTranscript}
          />
        )}
      </div>

      {/* Chapters Sidebar */}
      {showChapters && (
        <ChaptersSidebar
          chapters={parsedChapters}
          currentChapterIdx={currentChapterIdx}
          onChapterClick={handleChapterClick}
          visible={showChapters}
        />
      )}

      {/* Modals */}
      {audioDescSettingsOpen && (
        <AudioDescSettingsModal
          open={audioDescSettingsOpen}
          onClose={() => setAudioDescSettingsOpen(false)}
          voices={voices}
          selectedVoice={selectedVoice}
          setSelectedVoice={setSelectedVoice}
          pitch={pitch}
          setPitch={setPitch}
          autoStop={autoStop}
          setAutoStop={setAutoStop}
          autoStart={autoStart}
          setAutoStart={setAutoStart}
          mode={audioDescMode}
          setMode={(m: string) => setAudioDescMode(m as 'tts' | 'audio' | 'sign')}
          hasAudioTrack={hasAudioTrack}
          hasSignTrack={hasSignTrack}
          ttsAvailable={ttsAvailable}
          ttsError={ttsError}
          isActive={audioDescActive}
          setIsActive={setAudioDescActive}
        />
      )}

      {settingsOpen && (
        <SettingsModal
          open={settingsOpen}
          onClose={() => setSettingsOpen(false)}
          showCC={showCC}
          showTranscript={showTranscript}
          hasCC={!!captions}
          hasTranscript={!!description}
        />
      )}

      {infoOpen && (
        <InfoModal
          open={infoOpen}
          onClose={() => setInfoOpen(false)}
        />
      )}
    </section>
  );
};

export default FullPlayer;