import React from 'react';
import { Chapter } from '../types/player';
import { formatTime } from '../utils/videoUtils';

interface ChaptersSidebarProps {
  chapters: Chapter[];
  currentChapterIdx: number;
  onChapterClick: (startTime: number) => void;
  visible: boolean;
}

const ChaptersSidebar: React.FC<ChaptersSidebarProps> = ({
  chapters,
  currentChapterIdx,
  onChapterClick,
  visible
}) => {
  if (!visible || chapters.length === 0) return null;

  return (
    <aside 
      style={{ 
        width: 220, 
        marginLeft: 16, 
        background: '#f0f4f8', 
        borderRadius: 4, 
        padding: 12, 
        height: '100%', 
        maxHeight: 480, 
        overflowY: 'auto' 
      }} 
      aria-label="Kapitel-Liste"
    >
      <h3 style={{ fontSize: 18, margin: '0 0 8px 0' }}>Kapitel</h3>
      <ol style={{ listStyle: 'none', padding: 0, margin: 0 }}>
        {chapters.map((ch, idx) => (
          <li key={idx} style={{ marginBottom: 8 }}>
            <button
              className="player-btn"
              style={{ 
                width: '100%', 
                textAlign: 'left', 
                background: idx === currentChapterIdx ? '#ffe082' : '#fff', 
                border: '1px solid #bbb', 
                borderRadius: 3, 
                padding: 6, 
                cursor: 'pointer', 
                fontWeight: idx === currentChapterIdx ? 'bold' : 'normal' 
              }}
              onClick={() => onChapterClick(ch.start)}
              aria-label={`Springe zu ${ch.title}`}
            >
              {ch.title} 
              <span style={{ float: 'right', color: '#888', fontSize: 12 }}>
                {formatTime(ch.start)}
              </span>
            </button>
          </li>
        ))}
      </ol>
    </aside>
  );
};

export default ChaptersSidebar;